#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
const ll MOD=1000000007;int main(){ll A,B,C,X,L1,R1,L2,R2;cin>>A>>B>>C>>X>>L1>>R1>>L2>>R2;vector<int>seen(C+1,-1),sequence;X=(A*X+B)%C+1;while(seen[X]<0){seen[X]=sequence.size();sequence.push_back(X);X=(A*X+B)%C+1;}int cycleStart=seen[X],cycle=sequence.size()-cycleStart;auto frequency=[&](ll L,ll R){vector<ll>f(C+1);auto addPrefix=[&](ll count,int sign){int before=min(count,(ll)cycleStart);for(int i=0;i<before;i++)f[sequence[i]]+=sign;if(count>cycleStart){ll full=(count-cycleStart)/cycle%MOD;int rest=(count-cycleStart)%cycle;for(int i=cycleStart;i<(int)sequence.size();i++)f[sequence[i]]+=sign*(full+(i-cycleStart<rest));}};addPrefix(R,1);addPrefix(L-1,-1);for(auto&v:f)v=(v%MOD+MOD)%MOD;return f;};auto a=frequency(L1,R1),b=frequency(L2,R2);vector<ll>pa(C+1),pb(C+1);for(int i=1;i<=C;i++){pa[i]=(pa[i-1]+a[i])%MOD;pb[i]=(pb[i-1]+b[i])%MOD;}auto sum=[](const vector<ll>&p,int l,int r){return (p[r]-p[l-1]+MOD)%MOD;};vector<double> root(C+1);for(ll q=2;q<=C;q++)root[q]=((q+1)+sqrt(double((q+1)*(q+1)-4)))/2;ll answer=0;for(ll y=1;y<=C;y++){if(!a[y]&&!b[y])continue;answer=(answer+2*a[y]%MOD*b[y])%MOD;for(ll q=1;q*y<=C;q++){ll l=max(y+1,q*y),r=min(C,(q+1)*y-1);if(l>r)continue;ll base=(a[y]*sum(pb,l,r)+b[y]*sum(pa,l,r))%MOD;answer=(answer+base*(q+1))%MOD;if(q==1){answer=(answer+base)%MOD;continue;}ll threshold=ll(root[q]*y)+1;auto extra=[&](ll x){return x*x+y*y>(q+1)*x*y;};while(threshold>l&&extra(threshold-1))threshold--;while(threshold<=r&&!extra(threshold))threshold++;threshold=max(threshold,l);if(threshold<=r){ll extraSum=(a[y]*sum(pb,threshold,r)+b[y]*sum(pa,threshold,r))%MOD;answer=(answer+extraSum)%MOD;}}}cout<<answer<<'\n';}
